\begin{align}
\textbf{多项式模型} \quad P(d|c) &= P(\langle t_1, \ldots, t_{n_d} \rangle | c) = \prod_{1 \le k \le n_d} P(X_k = t_k | c) \tag{13.13} \\
\textbf{伯努利模型} \quad P(d|c) &= P(\langle e_1, \ldots, e_M \rangle | c) = \prod_{1 \le i \le M} P(U_i = e_i | c). \tag{13.14}
\end{align}
